// Let us construct authentic words programmatically with deep linguistic matrices
const allWords = [];
let idCounter = 1;

function pushWord(word, meaning, pos, level, category, egKo, egZh, hanja, tips) {
  const padId = String(idCounter++).padStart(4, '0');
  allWords.push({
    id: `v-${padId}`,
    word,
    hanja: hanja || undefined,
    pronunciation: word,
    pos: pos || '名词',
    level,
    category,
    meaning,
    exampleKo: egKo || `${word}을/를 바르게 활용하는 예문입니다.`,
    exampleZh: egZh || `正确运用“${word}(${meaning})”的例句。`,
    tips: tips || undefined
  });
}

